import { BlockTuneData } from '@editorjs/editorjs/types/block-tunes/block-tune-data'
import { HyperlinkTuneData } from '../HyperlinkTune/HyperlinkTune'
import SmartQuotes from './SmartQuotes'
import he from 'he'
import { jsonrepair } from 'jsonrepair'

export interface BlockTuneDataPushword extends BlockTuneData {
  anchor?: string
  textAlign?: string
  class?: string
  linkTune?: HyperlinkTuneData
}
export interface MarkdownChunk {
  text: string
  /** 0-based line range of the chunk in the source, end inclusive. */
  startLine: number
  endLine: number
  /** The blank-line run that followed the chunk in the source; '' for the last one. */
  separatorAfter: string
}

/**
 * Utilitaires pour l'export Markdown
 */
export class MarkdownUtils {
  /**
   * Split markdown into its block chunks — the unit the editor round-trips on.
   * Chunk texts are byte-for-byte what the historical
   * `replace(/\n\s*\n+/g, '\n\n')` + `split('\n\n')` produced (the parser and
   * the outline panel MUST share this rule), with one exception: a blank line
   * inside a fenced code block does NOT split. Splitting there handed the
   * editor half a fence, and a `## ` comment in the code then read as a real
   * heading — so the fence is atomic here, as it is to the renderer.
   *
   * Each chunk keeps its line range in the source so chunk N maps back to
   * source lines, and the separator that followed it so a rewrite can put the
   * author's blank lines back instead of normalising them. Whitespace-only
   * input yields no chunk, mirroring the parser's empty-content guard.
   */
  static chunkMarkdown(markdown: string): MarkdownChunk[] {
    if (markdown.trim() === '') return []

    const fences = MarkdownUtils.fencedRanges(markdown)
    const insideFence = (index: number): boolean =>
      fences.some(([from, to]) => index >= from && index < to)

    const chunks: MarkdownChunk[] = []
    const separator = /\n\s*\n+/g
    let start = 0
    let startLine = 0
    const pushChunk = (end: number, separatorAfter: string): void => {
      const text = markdown.slice(start, end)
      chunks.push({
        text,
        startLine,
        endLine: startLine + MarkdownUtils.countLines(text),
        separatorAfter,
      })
    }

    let match: RegExpExecArray | null
    while ((match = separator.exec(markdown)) !== null) {
      if (insideFence(match.index)) continue

      pushChunk(match.index, match[0])
      startLine += MarkdownUtils.countLines(markdown.slice(start, separator.lastIndex))
      start = separator.lastIndex
    }
    pushChunk(markdown.length, '')

    return chunks
  }

  /**
   * Character ranges covered by fenced code blocks, `[from, to)` — `from` at the
   * opening fence's first character, `to` at the end of the closing fence line,
   * its newline excluded so the separator that follows the fence still splits.
   * An unclosed fence runs to the end of the document, which is what the
   * renderer does with it too. CommonMark rules: up to three spaces of indent,
   * a closing run at least as long as the opening one and nothing but space
   * after it, and no backtick in a backtick fence's info string.
   */
  private static fencedRanges(markdown: string): [number, number][] {
    const fence = /^ {0,3}(`{3,}|~{3,})(.*)$/
    const ranges: [number, number][] = []
    let open: { marker: string; from: number } | null = null
    let offset = 0

    for (const line of markdown.split('\n')) {
      const match = fence.exec(line)
      if (match !== null) {
        const marker = match[1]!
        const info = match[2]!
        if (open === null) {
          if (!(marker.startsWith('`') && info.includes('`'))) {
            open = { marker, from: offset }
          }
        } else if (
          marker[0] === open.marker[0] &&
          marker.length >= open.marker.length &&
          info.trim() === ''
        ) {
          ranges.push([open.from, offset + line.length])
          open = null
        }
      }
      offset += line.length + 1
    }
    if (open !== null) ranges.push([open.from, markdown.length])

    return ranges
  }

  /**
   * Rejoin chunk texts with the source's own separators, positionally: the Nth
   * gap keeps the Nth blank-line run the document had. A rail edit then leaves
   * the spacing it did not touch byte-identical instead of collapsing every
   * blank-line run to one.
   */
  static joinChunks(texts: string[], separators: string[]): string {
    return texts
      .map((text, index) => (index === 0 ? text : (separators[index - 1] ?? '\n\n') + text))
      .join('')
  }

  private static countLines(text: string): number {
    return (text.match(/\n/g) ?? []).length
  }
  static wrapWithLink(markdown: string, tunes: BlockTuneDataPushword): string {
    if (!tunes.linkTune) {
      return MarkdownUtils.addAttributes(markdown, tunes)
    }

    const linkTune: HyperlinkTuneData = tunes.linkTune

    if (!linkTune.url) {
      return markdown
    }

    let link = `[${markdown}](${linkTune.url}){`
    if (linkTune.targetBlank) {
      link += `target="_blank"`
    }
    link += `}`
    link = link.replace(/{}/g, '')

    if (linkTune.hideForBot) {
      link = '#' + link
    }
    return link
  }

  static getAttributes(tunes: BlockTuneDataPushword): string {
    let result = ''

    // anchor
    const anchor = tunes?.anchor
    if (anchor && anchor !== '') {
      result += `#${anchor}`
    }

    const alignment = tunes?.textAlign
    if (alignment && alignment !== 'left') {
      const alignmentClass =
        alignment === 'center' ? 'text-center' : alignment === 'right' ? 'text-right' : ''
      if (alignmentClass) {
        result += `.${alignmentClass}`
      }
    }

    const className = tunes?.class
    if (className && className !== '') {
      result += `.${className}`
    }

    return result
  }

  private static formatAttributes(tunes: BlockTuneDataPushword): string {
    return MarkdownUtils.getAttributes(tunes).replace(/\s+/g, ' ').trim()
  }

  static addAttributes(markdown: string, tunes: BlockTuneDataPushword): string {
    const attrs = MarkdownUtils.formatAttributes(tunes)
    if (attrs !== '') {
      return `{${attrs}}\n${markdown}`
    }
    return markdown
  }

  static addInlineAttributes(markdown: string, tunes: BlockTuneDataPushword): string {
    const attrs = MarkdownUtils.formatAttributes(tunes)
    if (attrs !== '') {
      const lines = markdown.split('\n')
      lines[0] = `${(lines[0] ?? '').trimEnd()} {${attrs}}`
      return lines.join('\n')
    }
    return markdown
  }

  static startWithAttribute(firstLine: string): boolean {
    const line = firstLine.trim()
    if (line.startsWith('{#') && (line.endsWith('#}') || !line.endsWith('}')))
      return false // it's a twig comment

    return (
      line.startsWith('{') &&
      line.endsWith('}') &&
      !line.startsWith('{{') &&
      !line.startsWith('{%')
    )
  }

  static parseAttributes(attributeLine: string): BlockTuneDataPushword {
    const tunes: BlockTuneData = {}

    const anchorMatch = attributeLine.match(/#([a-zA-Z0-9_-]+)/) ?? attributeLine.match(/id=([a-zA-Z0-9_-]+)/)
    if (anchorMatch) {
      tunes.anchor = anchorMatch[1]
    }

    const alignmentMatch = attributeLine.match(/\.text-(left|center|right)/)
    if (alignmentMatch) {
      tunes.textAlign = alignmentMatch[1]
      attributeLine = attributeLine.replace(alignmentMatch[0], '')
    }

    const classMatch = attributeLine.match(/\.([a-zA-Z0-9_-]+)/g)
    if (classMatch) {
      tunes.class = classMatch.join(' ')
    }

    return tunes
  }

  static retrieveMarkdownWithoutTunes(markdown: string): string {
    markdown = markdown.trim()
    const lines = markdown.split('\n')
    const firstLine = lines[0] ?? ''

    // Parse attributes if present
    if (MarkdownUtils.startWithAttribute(firstLine)) {
      lines[0] = ''
      return lines.join('\n').trim()
    }

    return markdown
  }

  static parseTunesFromMarkdown(markdown: string): {
    tunes: BlockTuneData
    markdown: string
  } {
    markdown = markdown.trim()
    const lines = markdown.split('\n')
    const firstLine = lines[0] ?? ''
    let tunes: BlockTuneData = {}

    // Parse attributes if present
    if (MarkdownUtils.startWithAttribute(firstLine)) {
      tunes = MarkdownUtils.parseAttributes(firstLine)
      lines[0] = ''
      markdown = lines.join('\n').trim()
    }

    return {
      tunes,
      markdown,
    }
  }

  // TODO : manage "ex" ~ "ample" or variable ?
  public static extractTwigFunctionProperties(
    funcName: string,
    markdown: string,
  ): string[] | null {
    const match = markdown.matchAll(/{{\s*([A-Za-z_]+)\((.*?)\)/g)
    if (!match) return null

    const matches = [...match]
    if (matches[0]?.[1] !== funcName) return null

    const argsString = matches[0]?.[0]?.substring(matches[0]?.[0]?.indexOf('(') + 1)
    return MarkdownUtils.extractTwigProperties(argsString)
  }

  static extractTwigProperties(argsString: string): null | string[] {
    const properties: string[] = []
    let current = ''
    let inQuote = false
    let quoteChar = ''
    let escaped = false

    for (const char of argsString) {
      // Arrêter si on trouve ')' en dehors des quotes
      if (char === ')' && !inQuote) {
        break
      }

      // - managed escaped quotes
      if (escaped) {
        // Ajouter le caractère échappé tel quel
        current += char === quoteChar ? char : '\\' + char
        escaped = false
        continue
      }

      if (char === '\\') {
        escaped = true
        continue
      }
      // - / managed escaped quotes

      if (['"', "'"].includes(char) && !inQuote) {
        // Début d'une chaîne quotée
        inQuote = true
        quoteChar = char
        continue
      }

      // Fin d'une chaîne quotée
      if (char === quoteChar && inQuote) {
        inQuote = false
        quoteChar = ''
        continue
      }

      if (!inQuote && ![' ', ','].includes(char)) {
        return null
        // throw new Error('Invalid twig function properties')
      }

      if (!inQuote && char === ',') {
        properties.push(current.trim())
        current = ''
        continue
      }

      current += char
    }

    properties.push(current.trim())

    return properties
  }

  /**
   * Parse a `snippet('name', { ...json... })` call.
   *
   * The first argument is a quoted snippet name; the optional second argument is
   * a JSON object of per-insertion params. Brace- and quote-aware so nested
   * objects/arrays and commas inside the JSON do not break parsing.
   */
  static extractSnippetCall(
    markdown: string,
  ): { name: string; params: Record<string, any> } | null {
    const open = markdown.match(/{{\s*snippet\s*\(/)
    if (!open || open.index === undefined) return null

    let i = markdown.indexOf('(', open.index) + 1
    while (i < markdown.length && /\s/.test(markdown[i] ?? '')) i++

    const quote = markdown[i]
    if (quote !== "'" && quote !== '"') return null
    i++

    let name = ''
    while (i < markdown.length && markdown[i] !== quote) {
      if (markdown[i] === '\\') {
        name += markdown[i + 1] ?? ''
        i += 2
        continue
      }
      name += markdown[i]
      i++
    }
    i++ // closing quote

    while (i < markdown.length && /\s/.test(markdown[i] ?? '')) i++

    let params: Record<string, any> = {}
    if (markdown[i] === ',') {
      i++
      while (i < markdown.length && /\s/.test(markdown[i] ?? '')) i++
      if (markdown[i] === '{') {
        params = MarkdownUtils.parseBalancedObject(markdown, i)
      }
    }

    return { name, params }
  }

  /**
   * Read a brace-balanced object literal starting at `start` and JSON-parse it.
   * Tolerates single quotes / trailing commas via jsonrepair.
   */
  private static parseBalancedObject(input: string, start: number): Record<string, any> {
    let depth = 0
    let inStr = false
    let strCh = ''
    let end = start

    for (let i = start; i < input.length; i++) {
      const c = input[i]
      if (inStr) {
        if (c === '\\') {
          i++
          continue
        }
        if (c === strCh) inStr = false
        continue
      }
      if (c === '"' || c === "'") {
        inStr = true
        strCh = c
        continue
      }
      if (c === '{') depth++
      else if (c === '}') {
        depth--
        if (depth === 0) {
          end = i + 1
          break
        }
      }
    }

    const raw = input.substring(start, end)
    try {
      return JSON.parse(raw)
    } catch {
      try {
        return JSON.parse(jsonrepair(raw))
      } catch {
        return {}
      }
    }
  }

  /**
   * Build a `snippet('name', {json})` Twig call. The params object is omitted
   * when empty so plain content snippets stay terse.
   */
  static buildSnippetCall(name: string, params: Record<string, any>): string {
    const keys = Object.keys(params || {})
    if (keys.length === 0) {
      return `{{ snippet(${MarkdownUtils.wrapInQuotes(name)}) }}`
    }
    return `{{ snippet(${MarkdownUtils.wrapInQuotes(name)}, ${JSON.stringify(params)}) }}`
  }

  /** True when the block is exactly a standalone snippet() call (not an inline mention). */
  static isSnippetBlock(markdown: string): boolean {
    const body = MarkdownUtils.retrieveMarkdownWithoutTunes(markdown).trim()
    if (!/^{{\s*snippet\s*\(/.test(body) || !/\)\s*}}$/.test(body)) return false
    return MarkdownUtils.extractSnippetCall(body) !== null
  }

  /**
   * Parse HTML attributes from a string and return them as a typed record
   */
  private static parseHtmlAttributes(attrString: string): Record<string, string> {
    const attrs: Record<string, string> = {}

    attrString.replace(
      /(\w+)\s*=\s*"([^"]*?)"/gi,
      (_match: string, key: string, value: string) => {
        attrs[key.toLowerCase()] = value
        return '' // required for .replace callback
      },
    )

    return attrs
  }

  private static convertAnchorToMarkdown(attrString: string, text: string): string {
    const attrs = MarkdownUtils.parseHtmlAttributes(attrString)
    const href = attrs.href || '#'
    const extras: string[] = []
    let obfuscate = false
    if (attrs.rel && attrs.rel === 'obfuscate') {
      obfuscate = true
    } else if (attrs.rel) extras.push(`rel="${attrs.rel}"`)
    if (attrs.target) extras.push(`target="${attrs.target}"`)
    if (attrs.class) extras.push(`class="${attrs.class}"`)

    return (
      (obfuscate ? '#' : '') +
      (extras.length ? `[${text}](${href}){${extras.join(' ')}}` : `[${text}](${href})`)
    )
  }

  static fixDash(text: string) {
    // Replace hyphens between numbers or spaces with en-dash
    text = text.replace(/(?<=[0-9 ])-(?=[0-9 ]|$)/g, '—')

    // Replace double hyphens with em-dash
    return text.replace(/ ?-- ?([^-]|$)/gs, '—' + '$1')
  }

  static makeUrlRelative(text: string): string {
    const host = window.pageHost
    const baseUrl = window.location.origin
    if (host === '') return text

    const toReplace = [
      `"${baseUrl}/${host}/`,
      `"${baseUrl}/`,
      `"https://${host}/`,
      `"http://${host}/`,
      `"://${host}/`,
    ]

    toReplace.forEach((replaceStr) => {
      text = text.split(replaceStr).join('"/')
    })

    return text
  }

  static fixer(text: string): string {
    const noBreakSpace = '\u00A0'
    const spaces = '\xE2\x80\xAF|\xC2\xAD|\xC2\xA0|\u00A0|\\s'

    text = MarkdownUtils.fixDash(text)
    text = MarkdownUtils.makeUrlRelative(text)

    if (window.pageLocale) {
      text = SmartQuotes(text, window.pageLocale)
    }

    text = text
      .replace(
        new RegExp(`([\\dº])(${spaces})+([º°%Ω฿₵¢₡$₫֏€ƒ₲₴₭£₤₺₦₨₱៛₹$₪৳₸₮₩¥]{1})`, 'g'), // \\w
        `$1${noBreakSpace}$3`,
      )
      .replace(/&nbsp;/gi, ' ')
      // CurlyQuote
      .replace(/([a-z])'([a-z])/gim, `$1’$2`)
      // Remove useless last space from inline tag
      .replace(/ <\/([a-z]+)>/gi, '</$1> ')
      // remove empty inline tag
      .replace(/ ?<(b|i|strong|em|span)> ?<\/(b|i|strong|em|span)> ?/gi, ' ')
      // remove empty inline tag
      .replace(/<(b|i|strong|em|span|a)[^>]*><\/(b|i|strong|em|span|a)>/gi, '')
      // NoSpaceBeforeComma
      .replace(new RegExp(`([^\\d\\s]+)[${spaces}]{1,},[${spaces}]{1,}`, 'gmu'), '$1, ')
      // NoSpaceBeforeDot
      .replace(new RegExp(`([^\\d\\s]+)[${spaces}]{1,}\\.[${spaces}]{1,}`, 'gmu'), '$1. ')

      // Ellipsis
      .replace(/\.{3,}/g, '…')
      // Ampersand
      .replace(/ &amp; /gi, ' & ')
      // Remove soft hyphens
      .replace(/&shy;/g, '')
      // Remove double spaces
      .replace(new RegExp(`[${spaces}]{2,}`, 'gmu'), ' ')

      // Dimension, replace 'x' between numbers with multiplication sign
      .replace(
        new RegExp(`(\\d+["']?)([${spaces}])?x([${spaces}])?(?=\\d)`, 'g'),
        '$1$2×$2',
      )
      .replace(/\(tm\)/gi, '™')
      .replace(/\(r\)/gi, '®')
      .replace(/\(c\)/gi, '©')

    return text
  }

  static convertInlineHtmlToMarkdown(html: string, applyTypographyFixes = true): string {
    if (applyTypographyFixes) {
      html = MarkdownUtils.fixer(html)
    }
    // Decode HTML entities first (including numeric ones like &#10140;)
    html = he.decode(html)
    // Convert non-breaking spaces to regular spaces (unless typography fixes are wanted)
    if (!applyTypographyFixes) {
      html = html.replace(/\u00A0/g, ' ')
    }

    return html
      .replace(/<(b|strong|em|i|a[^>]*)> /gi, ' <$1>')
      .replace(/ <\/(b|strong|em|i|a[^>]*)>/gi, '</$1> ')
      .replace(/<(b|strong)(?: [^>]*)?>(.+?)<\/(b|strong)>/gi, '**$2**')
      .replace(/<(i|em)(?: [^>]*)?>(.+?)<\/(i|em)>/gi, '_$2_')
      .replace(/<code(?: [^>]*)?>(.+?)<\/code>/gi, '`$1`')
      .replace(/<s(?: [^>]*)?>(.+?)<\/s>/gi, '~~$1~~')
      .replace(/<sup(?: [^>]*)?>(.+?)<\/sup>/gi, '^$1^')
      .replace(/<sub(?: [^>]*)?>(.+?)<\/sub>/gi, '~$1~')
      .replace(/<u(?: [^>]*)?>(.+?)<\/u>/gi, '<u>$1</u>')
      .replace(/<small(?: [^>]*)?>(.+?)<\/small>/gi, '<small>$1</small>')
      .replace(/<mark(?: [^>]*)?>(.+?)<\/mark>/gi, '<mark>$1</mark>')
      .replace(/<a\s+([^>]+)>(.+?)<\/a>/gi, (_match, attrString, text) =>
        MarkdownUtils.convertAnchorToMarkdown(attrString, text),
      )
      .replace(/<br\s*\/?>/gi, '\n') // Convert <br> to newlines
      .replace(/<div>/gi, '\n') // Convert <div> (line wraps in contenteditable) to newlines
      .replace(/<\/div>/gi, '')
  }

  private static convertMarkdownToAnchor(markdown: string): string {
    const isObfuscated = markdown.startsWith('#')
    const linkText = isObfuscated ? markdown.substring(1) : markdown

    // Match markdown link with optional attributes: [text](url{attrs})
    const linkWithAttrsRegex = /\[([^\]]+)\]\(([^){]+)\)\{([^}]+)\}/
    const simpleLinkRegex = /\[([^\]]+)\]\(([^)]+)\)/

    let match = linkText.match(linkWithAttrsRegex)
    let text: string
    let href: string
    let attrsString = ''

    if (match) {
      text = match[1] ?? ''
      href = match[2] ?? ''
      attrsString = match[3] ?? ''
    } else {
      match = linkText.match(simpleLinkRegex)
      if (!match) return markdown
      text = match[1] ?? ''
      href = match[2] ?? ''
    }

    if (isObfuscated) {
      attrsString = attrsString ? `rel="obfuscate" ${attrsString}` : 'rel="obfuscate"'
    }

    const attrs = attrsString ? ' ' + attrsString : ''
    return `<a href="${href}"${attrs}>${text}</a>`
  }

  static convertInlineMarkdownToHtml(markdown: string): string {
    return markdown
      .replace(/\*\*(.+?)\*\*/g, '<b>$1</b>')
      .replace(/_(.+?)_/g, '<i>$1</i>')
      .replace(/`(.+?)`/g, '<code class="inline-code">$1</code>')
      .replace(/~~(.+?)~~/g, '<s class="cdx-strikethrough">$1</s>')
      .replace(/#?\[([^\]]+)\]\(([^){]+)\)(?:\{([^}]+)\})?/g, (match) =>
        MarkdownUtils.convertMarkdownToAnchor(match),
      )
      .replace(/\n/g, '<br>') // Convert newlines to <br>
  }

  /**
   * Formate le contenu Markdown avec Prettier
   */
  private static prettierPromise: Promise<{ prettier: any; plugin: any }> | null = null

  private static loadScript(src: string): Promise<void> {
    return new Promise((resolve, reject) => {
      const existing = document.querySelector(`script[src="${src}"]`)
      if (existing) {
        resolve()
        return
      }
      const script = document.createElement('script')
      script.src = src
      script.async = true
      script.onload = () => resolve()
      script.onerror = () => reject(new Error(`Failed to load ${src}`))
      document.head.appendChild(script)
    })
  }

  private static loadPrettier(): Promise<{ prettier: any; plugin: any }> {
    if (!MarkdownUtils.prettierPromise) {
      MarkdownUtils.prettierPromise = Promise.all([
        MarkdownUtils.loadScript('/bundles/pushwordadminblockeditor/prettier/standalone.js'),
        MarkdownUtils.loadScript('/bundles/pushwordadminblockeditor/prettier/markdown.js'),
      ]).then(() => ({
        prettier: (window as any).prettier,
        plugin: (window as any).prettierPlugins?.markdown,
      }))
    }
    return MarkdownUtils.prettierPromise
  }

  public static async formatMarkdownWithPrettier(
    markdownContent: string,
  ): Promise<string> {
    try {
      const { prettier, plugin } = await MarkdownUtils.loadPrettier()

      const formatted = await prettier.format(markdownContent, {
        parser: 'markdown',
        plugins: [plugin],
        proseWrap: 'preserve',
        tabWidth: 2,
        useTabs: false,
      })

      return formatted.trim()
    } catch {
      console.error('Erreur lors du formatage Prettier du Markdown', {
        content: markdownContent,
      })

      return markdownContent
    }
  }

  public static wrapInQuotes(text: string): string {
    if (!text.includes("'")) return "'" + text + "'"

    const escaped = text.replace('"', '\\' + '"')
    return `"${escaped}"`
  }
}

export function e(text: string): string {
  return MarkdownUtils.wrapInQuotes(text)
}
