import Toolbox from './toolbox';
import * as $ from './utils/dom';
import throttled from './utils/throttled';

import {
  IconDirectionLeftDown,
  IconDirectionRightDown,
  IconDirectionUpRight,
  IconDirectionDownRight,
  IconCross,
  IconPlus,
  IconAlignLeft,
  IconAlignCenter,
  IconAlignRight
} from '@codexteam/icons';

const CSS = {
  wrapper: 'tc-wrap',
  wrapperReadOnly: 'tc-wrap--readonly',
  table: 'tc-table',
  row: 'tc-row',
  withHeadings: 'tc-table--heading',
  rowSelected: 'tc-row--selected',
  cell: 'tc-cell',
  cellSelected: 'tc-cell--selected',
  cellColspan: 'tc-cell--colspan',
  addRow: 'tc-add-row',
  addRowDisabled: 'tc-add-row--disabled',
  addColumn: 'tc-add-column',
  addColumnDisabled: 'tc-add-column--disabled',
};

/**
 * @typedef {object} TableConfig
 * @description Tool's config from Editor
 * @property {boolean} withHeadings — Uses the first line as headings
 * @property {string[][]} withHeadings — two-dimensional array with table contents
 */
interface TableConfig {
  withHeadings?: boolean;
  content?: string[][];
  rows?: number;
  cols?: number;
  maxCols?: number;
  maxRows?: number;
  [key: string]: any;
}

/**
 * @typedef {object} TableData - object with the data transferred to form a table
 * @property {number} rows - number of rows in the table
 * @property {number} cols - number of columns in the table
 */
interface TableData {
  withHeadings?: boolean;
  content?: string[][];
  [key: string]: any;
}


/**
 * Generates and manages table contents.
 */
export default class Table {
  readOnly: boolean;
  api: any;
  data: TableData;
  config: TableConfig;
  wrapper: HTMLElement | null;
  table: HTMLElement | null;
  toolboxColumn: Toolbox;
  toolboxRow: Toolbox;
  hoveredRow: number;
  hoveredColumn: number;
  selectedRow: number;
  selectedColumn: number;
  /** Per-column GFM alignment; '' = default/none, else 'left' | 'center' | 'right'. */
  columnAlignments: string[];
  tunes: { withHeadings: boolean };
  focusedCell: { row: number; column: number };
  documentClicked: (event: MouseEvent) => void;

  /**
   * Creates
   *
   * @constructor
   * @param {boolean} readOnly - read-only mode flag
   * @param {object} api - Editor.js API
   * @param {TableData} data - Editor.js API
   * @param {TableConfig} config - Editor.js API
   */
  constructor(readOnly: boolean, api: any, data: TableData, config: TableConfig) {
    this.readOnly = readOnly;
    this.api = api;
    this.data = data;
    this.config = config;

    // Per-column alignment, grown/shifted as columns are added/removed; seeded from data in fill().
    this.columnAlignments = [];

    /**
     * DOM nodes
     */
    this.wrapper = null;
    this.table = null;

    /**
     * Toolbox for managing of columns
     */
    this.toolboxColumn = this.createColumnToolbox();
    this.toolboxRow = this.createRowToolbox();

    /**
     * Create table and wrapper elements
     */
    this.createTableWrapper();

    // Current hovered row index
    this.hoveredRow = 0;

    // Current hovered column index
    this.hoveredColumn = 0;

    // Index of last selected row via toolbox
    this.selectedRow = 0;

    // Index of last selected column via toolbox
    this.selectedColumn = 0;

    // Additional settings for the table
    this.tunes = {
      withHeadings: false
    };

    /**
     * Resize table to match config/data size
     */
    this.resize();

    /**
     * Fill the table with data
     */
    this.fill();

    /**
     * The cell in which the focus is currently located, if 0 and 0 then there is no focus
     * Uses to switch between cells with buttons
     */
    this.focusedCell = {
      row: 0,
      column: 0
    };

    /**
     * Global click listener allows to delegate clicks on some elements
     */
    this.documentClicked = (event: MouseEvent) => {
      const clickedInsideTable = (event.target as Element).closest(`.${CSS.table}`) !== null;
      const outsideTableClicked = (event.target as Element).closest(`.${CSS.wrapper}`) === null;
      const clickedOutsideToolboxes = clickedInsideTable || outsideTableClicked;

      if (clickedOutsideToolboxes) {
        this.hideToolboxes();
      }

      const clickedOnAddRowButton = (event.target as Element).closest(`.${CSS.addRow}`);
      const clickedOnAddColumnButton = (event.target as Element).closest(`.${CSS.addColumn}`);

      /**
       * Also, check if clicked in current table, not other (because documentClicked bound to the whole document)
       */
      if (clickedOnAddRowButton && clickedOnAddRowButton.parentNode === this.wrapper) {
        this.addRow(undefined, true);
        this.hideToolboxes();
      } else if (clickedOnAddColumnButton && clickedOnAddColumnButton.parentNode === this.wrapper) {
        this.addColumn(undefined, true);
        this.hideToolboxes();
      }
    };

    if (!this.readOnly) {
      this.bindEvents();
    }
  }

  /**
   * Returns the rendered table wrapper
   *
   * @returns {Element}
   */
  getWrapper(): HTMLElement {
    return this.wrapper!;
  }

  /**
   * Hangs the necessary handlers to events
   */
  bindEvents(): void {
    // set the listener to close toolboxes when click outside
    document.addEventListener('click', this.documentClicked);

    // Update toolboxes position depending on the mouse movements
    this.table!.addEventListener('mousemove', throttled(150, (event: MouseEvent) => this.onMouseMoveInTable(event)), { passive: true });

    // Controls some of the keyboard buttons inside the table
    this.table!.onkeypress = (event: KeyboardEvent) => this.onKeyPressListener(event);

    // Tab is executed by default before keypress, so it must be intercepted on keydown
    this.table!.addEventListener('keydown', (event) => this.onKeyDownListener(event));

    // Determine the position of the cell in focus
    this.table!.addEventListener('focusin', event => this.focusInTableListener(event as FocusEvent));

    // Re-evaluate `->` colspan markers as the user edits cells
    this.table!.addEventListener('input', () => this.updateColspanMarkers());
  }

  /**
   * Configures and creates the toolbox for manipulating with columns
   *
   * @returns {Toolbox}
   */
  createColumnToolbox(): Toolbox {
    return new Toolbox({
      api: this.api,
      cssModifier: 'column',
      items: [
        {
          label: this.api.i18n.t('Add column to left'),
          icon: IconDirectionLeftDown,
          hideIf: () => {
            return this.numberOfColumns === this.config.maxCols
          },
          onClick: () => {
            this.addColumn(this.selectedColumn, true);
            this.hideToolboxes();
          }
        },
        {
          label: this.api.i18n.t('Add column to right'),
          icon: IconDirectionRightDown,
          hideIf: () => {
            return this.numberOfColumns === this.config.maxCols
          },
          onClick: () => {
            this.addColumn(this.selectedColumn + 1, true);
            this.hideToolboxes();
          }
        },
        {
          label: this.api.i18n.t('Align left'),
          icon: IconAlignLeft,
          onClick: () => {
            this.setColumnAlignment(this.selectedColumn, 'left');
            this.hideToolboxes();
          }
        },
        {
          label: this.api.i18n.t('Align center'),
          icon: IconAlignCenter,
          onClick: () => {
            this.setColumnAlignment(this.selectedColumn, 'center');
            this.hideToolboxes();
          }
        },
        {
          label: this.api.i18n.t('Align right'),
          icon: IconAlignRight,
          onClick: () => {
            this.setColumnAlignment(this.selectedColumn, 'right');
            this.hideToolboxes();
          }
        },
        {
          label: this.api.i18n.t('Delete column'),
          icon: IconCross,
          hideIf: () => {
            return this.numberOfColumns === 1;
          },
          confirmationRequired: true,
          onClick: () => {
            this.deleteColumn(this.selectedColumn);
            this.hideToolboxes();
          }
        }
      ],
      onOpen: () => {
        this.selectColumn(this.hoveredColumn);
        this.hideRowToolbox();
      },
      onClose: () => {
        this.unselectColumn();
      }
    });
  }

  /**
   * Configures and creates the toolbox for manipulating with rows
   *
   * @returns {Toolbox}
   */
  createRowToolbox(): Toolbox {
    return new Toolbox({
      api: this.api,
      cssModifier: 'row',
      items: [
        {
          label: this.api.i18n.t('Add row above'),
          icon: IconDirectionUpRight,
          hideIf: () => {
            return this.numberOfRows === this.config.maxRows
          },
          onClick: () => {
            this.addRow(this.selectedRow, true);
            this.hideToolboxes();
          }
        },
        {
          label: this.api.i18n.t('Add row below'),
          icon: IconDirectionDownRight,
          hideIf: () => {
            return this.numberOfRows === this.config.maxRows
          },
          onClick: () => {
            this.addRow(this.selectedRow + 1, true);
            this.hideToolboxes();
          }
        },
        {
          label: this.api.i18n.t('Delete row'),
          icon: IconCross,
          hideIf: () => {
            return this.numberOfRows === 1;
          },
          confirmationRequired: true,
          onClick: () => {
            this.deleteRow(this.selectedRow);
            this.hideToolboxes();
          }
        }
      ],
      onOpen: () => {
        this.selectRow(this.hoveredRow);
        this.hideColumnToolbox();
      },
      onClose: () => {
        this.unselectRow();
      }
    });
  }

  /**
   * When you press enter it moves the cursor down to the next row
   * or creates it if the click occurred on the last one
   */
  moveCursorToNextRow(): void {
    if (this.focusedCell.row !== this.numberOfRows) {
      this.focusedCell.row += 1;
      this.focusCell(this.focusedCell);
    } else {
      this.addRow();
      this.focusedCell.row += 1;
      this.focusCell(this.focusedCell);
      this.updateToolboxesPosition(0, 0);
    }
  }

  /**
   * Get table cell by row and col index
   *
   * @param {number} row - cell row coordinate
   * @param {number} column - cell column coordinate
   * @returns {HTMLElement}
   */
  getCell(row: number, column: number): HTMLElement {
    return this.table!.querySelectorAll(`.${CSS.row}:nth-child(${row}) .${CSS.cell}`)[column - 1] as HTMLElement;
  }

  /**
   * Get table row by index
   *
   * @param {number} row - row coordinate
   * @returns {HTMLElement}
   */
  getRow(row: number): HTMLElement {
    return this.table!.querySelector(`.${CSS.row}:nth-child(${row})`) as HTMLElement;
  }

  /**
   * The parent of the cell which is the row
   *
   * @param {HTMLElement} cell - cell element
   * @returns {HTMLElement}
   */
  getRowByCell(cell: HTMLElement): HTMLElement {
    return cell.parentElement as HTMLElement;
  }

  /**
   * Ger row's first cell
   *
   * @param {Element} row - row to find its first cell
   * @returns {Element}
   */
  getRowFirstCell(row: HTMLElement): HTMLElement {
    return row.querySelector(`.${CSS.cell}:first-child`) as HTMLElement;
  }

  /**
   * Set the sell's content by row and column numbers
   *
   * @param {number} row - cell row coordinate
   * @param {number} column - cell column coordinate
   * @param {string} content - cell HTML content
   */
  setCellContent(row: number, column: number, content: string): void {
    const cell = this.getCell(row, column);

    cell.innerHTML = content;
  }

  /**
   * Add column in table on index place
   * Add cells in each row
   *
   * @param {number} columnIndex - number in the array of columns, where new column to insert, -1 if insert at the end
   * @param {boolean} [setFocus] - pass true to focus the first cell
   */
  addColumn(columnIndex: number | undefined = -1, setFocus = false): void {
    const numberOfColumns = this.numberOfColumns;
     /**
      * Check if the number of columns has reached the maximum allowed columns specified in the configuration,
      * and if so, exit the function to prevent adding more columns beyond the limit.
      */
    if (this.config && this.config.maxCols && this.numberOfColumns >= this.config.maxCols) {
      return;
  }

    /**
     * Iterate all rows and add a new cell to them for creating a column
     */
    for (let rowIndex = 1; rowIndex <= this.numberOfRows; rowIndex++) {
      let cell;
      const cellElem = this.createCell();

      if (columnIndex! > 0 && columnIndex! <= numberOfColumns) {
        cell = this.getCell(rowIndex, columnIndex!);

        $.insertBefore(cellElem, cell);
      } else {
        cell = this.getRow(rowIndex).appendChild(cellElem);
      }

      /**
       * Autofocus first cell
       */
      if (rowIndex === 1) {
        const firstCell = this.getCell(rowIndex, columnIndex! > 0 ? columnIndex! : numberOfColumns + 1);

        if (firstCell && setFocus) {
          $.focus(firstCell);
        }
      }
    }

    const addColButton = this.wrapper!.querySelector(`.${CSS.addColumn}`);
    if (this.config?.maxCols && this.numberOfColumns > this.config.maxCols - 1 && addColButton ){
      addColButton.classList.add(CSS.addColumnDisabled);
    }

    // Keep per-column alignment aligned with the new column layout (default for the new one).
    const alignmentInsertAt = (columnIndex! > 0 && columnIndex! <= numberOfColumns) ? columnIndex! - 1 : numberOfColumns;
    this.columnAlignments.splice(alignmentInsertAt, 0, '');
    this.applyColumnAlignments();

    this.addHeadingAttrToFirstRow();
    this.updateColspanMarkers();
  };

  /**
   * Add row in table on index place
   *
   * @param {number} index - number in the array of rows, where new column to insert, -1 if insert at the end
   * @param {boolean} [setFocus] - pass true to focus the inserted row
   * @returns {HTMLElement} row
   */
  addRow(index: number | undefined = -1, setFocus = false): HTMLElement | undefined {
    let insertedRow;
    const rowElem = $.make('div', CSS.row);

    if (this.tunes.withHeadings) {
      this.removeHeadingAttrFromFirstRow();
    }

    /**
     * We remember the number of columns, because it is calculated
     * by the number of cells in the first row
     * It is necessary that the first line is filled in correctly
     */
    const numberOfColumns = this.numberOfColumns;
     /**
      * Check if the number of rows has reached the maximum allowed rows specified in the configuration,
      * and if so, exit the function to prevent adding more columns beyond the limit.
      */
    if (this.config && this.config.maxRows && this.numberOfRows >= this.config.maxRows) {
      return;
    }

    if (index! > 0 && index! <= this.numberOfRows) {
      const row = this.getRow(index!);

      insertedRow = $.insertBefore(rowElem, row) as HTMLElement;
    } else {
      insertedRow = this.table!.appendChild(rowElem);
    }

    this.fillRow(insertedRow, numberOfColumns);

    if (this.tunes.withHeadings) {
      this.addHeadingAttrToFirstRow();
    }

    const insertedRowFirstCell = this.getRowFirstCell(insertedRow);

    if (insertedRowFirstCell && setFocus) {
      $.focus(insertedRowFirstCell);
    }

    const addRowButton = this.wrapper!.querySelector(`.${CSS.addRow}`);
    if (this.config && this.config.maxRows && this.numberOfRows >= this.config.maxRows && addRowButton) {
      addRowButton.classList.add(CSS.addRowDisabled);
    }

    // New row's cells must inherit their columns' alignment.
    this.applyColumnAlignments();

    return insertedRow;
  };

  /**
   * Delete a column by index
   *
   * @param {number} index
   */
  deleteColumn(index: number): void {
    for (let i = 1; i <= this.numberOfRows; i++) {
      const cell = this.getCell(i, index);

      if (!cell) {
        return;
      }

      cell.remove();
    }
    const addColButton = this.wrapper!.querySelector(`.${CSS.addColumn}`);
    if (addColButton) {
      addColButton.classList.remove(CSS.addColumnDisabled);
    }

    this.columnAlignments.splice(index - 1, 1);
    this.applyColumnAlignments();
    this.updateColspanMarkers();
  }

  /**
   * Delete a row by index
   *
   * @param {number} index
   */
  deleteRow(index: number): void {
    this.getRow(index).remove();
    const addRowButton = this.wrapper!.querySelector(`.${CSS.addRow}`);
    if (addRowButton) {
      addRowButton.classList.remove(CSS.addRowDisabled);
    }

    this.addHeadingAttrToFirstRow();
  }

  /**
   * Create a wrapper containing a table, toolboxes
   * and buttons for adding rows and columns
   *
   * @returns {HTMLElement} wrapper - where all buttons for a table and the table itself will be
   */
  createTableWrapper(): void {
    this.wrapper = $.make('div', CSS.wrapper);
    this.table = $.make('div', CSS.table);

    if (this.readOnly) {
      this.wrapper.classList.add(CSS.wrapperReadOnly);
    }

    this.wrapper.appendChild(this.toolboxRow.element);
    this.wrapper.appendChild(this.toolboxColumn.element);
    this.wrapper.appendChild(this.table);

    if (!this.readOnly) {
      const addColumnButton = $.make('div', CSS.addColumn, {
        innerHTML: IconPlus
      });
      const addRowButton = $.make('div', CSS.addRow, {
        innerHTML: IconPlus
      });

      this.wrapper.appendChild(addColumnButton);
      this.wrapper.appendChild(addRowButton);
    }
  }

  /**
   * Returns the size of the table based on initial data or config "size" property
   *
   * @return {{rows: number, cols: number}} - number of cols and rows
   */
  computeInitialSize(): { rows: number; cols: number } {
    const content = this.data && this.data.content;
    const isValidArray = Array.isArray(content);
    const isNotEmptyArray = isValidArray ? content!.length : false;
    const contentRows = isValidArray ? content!.length : undefined;
    const contentCols = isNotEmptyArray ? content![0]!.length : undefined;
    const parsedRows = Number.parseInt(this.config && this.config.rows as any);
    const parsedCols = Number.parseInt(this.config && this.config.cols as any);

    /**
     * Value of config have to be positive number
     */
    const configRows = !isNaN(parsedRows) && parsedRows > 0 ? parsedRows : undefined;
    const configCols = !isNaN(parsedCols) && parsedCols > 0 ? parsedCols : undefined;
    const defaultRows = 2;
    const defaultCols = 2;
    const rows = contentRows || configRows || defaultRows;
    const cols = contentCols || configCols || defaultCols;

    return {
      rows: rows,
      cols: cols
    };
  }

  /**
   * Resize table to match config size or transmitted data size
   *
   * @return {{rows: number, cols: number}} - number of cols and rows
   */
  resize(): void {
    const { rows, cols } = this.computeInitialSize();

    for (let i = 0; i < rows; i++) {
      this.addRow();
    }

    for (let i = 0; i < cols; i++) {
      this.addColumn();
    }
  }

  /**
   * Fills the table with data passed to the constructor
   *
   * @returns {void}
   */
  fill(): void {
    const data = this.data;

    if (data && data.content) {
      for (let i = 0; i < data.content.length; i++) {
        const rowContent = data.content[i]!;
        for (let j = 0; j < rowContent.length; j++) {
          this.setCellContent(i + 1, j + 1, rowContent[j] ?? '');
        }
      }
    }

    // Seed per-column alignment from saved data, normalized to the current column count.
    if (Array.isArray(data && data.columnAlignments)) {
      this.columnAlignments = [];
      for (let c = 0; c < this.numberOfColumns; c++) {
        this.columnAlignments.push(data.columnAlignments[c] || '');
      }
      this.applyColumnAlignments();
    }

    this.updateColspanMarkers();
  }

  /**
   * Renders `->` colspan markers as real spanning cells: a cell preceding one or
   * more `->` cells spans across them so its content fills the merged width, while
   * the (transparent) marker cells overlap the spanned area and stay clickable for
   * editing/removing the `->`. A marker in the first column is ignored — it has no
   * cell to merge into, matching the markdown renderer.
   *
   * Spanning needs an explicit, equal track count (`--table-cols`); `auto-fit`
   * would recompute the tracks per row once cells start spanning and misalign the
   * columns across rows.
   *
   * @returns {void}
   */
  updateColspanMarkers(): void {
    if (!this.table) {
      return;
    }

    this.table.style.setProperty('--table-cols', String(this.numberOfColumns));

    this.table.querySelectorAll(`.${CSS.row}`).forEach((row) => {
      const cells = Array.from(row.querySelectorAll<HTMLElement>(`.${CSS.cell}`));

      cells.forEach((cell, index) => {
        const isMarker = index > 0 && cell.textContent!.trim() === '->';

        cell.classList.toggle(CSS.cellColspan, isMarker);

        // Pin every cell to its own track line so a spanning cell can overlap the
        // marker cells that follow it without shifting the others.
        cell.style.gridColumnStart = String(index + 1);

        if (isMarker) {
          cell.style.gridColumnEnd = '';

          return;
        }

        let run = 0;
        for (
          let next = index + 1;
          next < cells.length && cells[next]!.textContent!.trim() === '->';
          next++
        ) {
          run++;
        }
        cell.style.gridColumnEnd = run > 0 ? `span ${run + 1}` : '';
      });
    });
  }

  /**
   * Set (or toggle off) the GFM alignment of a column and re-render it.
   *
   * @param {number} column - 1-based column index
   * @param {string} alignment - 'left' | 'center' | 'right'
   */
  setColumnAlignment(column: number, alignment: string): void {
    if (column <= 0) {
      return;
    }

    const current = this.columnAlignments[column - 1] || '';

    this.columnAlignments[column - 1] = current === alignment ? '' : alignment;
    this.applyColumnAlignments();
  }

  /**
   * Apply each column's alignment to its cells as inline `text-align`.
   *
   * @returns {void}
   */
  applyColumnAlignments(): void {
    for (let row = 1; row <= this.numberOfRows; row++) {
      for (let column = 1; column <= this.numberOfColumns; column++) {
        const cell = this.getCell(row, column);

        if (cell) {
          cell.style.textAlign = this.columnAlignments[column - 1] || '';
        }
      }
    }
  }

  /**
   * Collect per-column alignment normalized to the current column count.
   *
   * @returns {string[]}
   */
  getColumnAlignments(): string[] {
    const alignments: string[] = [];

    for (let column = 0; column < this.numberOfColumns; column++) {
      alignments.push(this.columnAlignments[column] || '');
    }

    return alignments;
  }

  /**
   * Fills a row with cells
   *
   * @param {HTMLElement} row - row to fill
   * @param {number} numberOfColumns - how many cells should be in a row
   */
  fillRow(row: HTMLElement, numberOfColumns: number): void {
    for (let i = 1; i <= numberOfColumns; i++) {
      const newCell = this.createCell();

      row.appendChild(newCell);
    }
  }

  /**
   * Creating a cell element
   *
   * @return {Element}
   */
  createCell(): HTMLElement {
    return $.make('div', CSS.cell, {
      contentEditable: !this.readOnly
    });
  }

  /**
   * Get number of rows in the table
   */
  get numberOfRows(): number {
    return this.table!.childElementCount;
  }

  /**
   * Get number of columns in the table
   */
  get numberOfColumns(): number {
    if (this.numberOfRows) {
      return this.table!.querySelectorAll(`.${CSS.row}:first-child .${CSS.cell}`).length;
    }

    return 0;
  }

  /**
   * Is the column toolbox menu displayed or not
   *
   * @returns {boolean}
   */
  get isColumnMenuShowing(): boolean {
    return this.selectedColumn !== 0;
  }

  /**
   * Is the row toolbox menu displayed or not
   *
   * @returns {boolean}
   */
  get isRowMenuShowing(): boolean {
    return this.selectedRow !== 0;
  }

  /**
   * Recalculate position of toolbox icons
   *
   * @param {Event} event - mouse move event
   */
  onMouseMoveInTable(event: MouseEvent): void {
    const { row, column } = this.getHoveredCell(event);

    this.hoveredColumn = column;
    this.hoveredRow = row;

    this.updateToolboxesPosition();
  }

  /**
   * Prevents default Enter behaviors
   * Adds Shift+Enter processing
   *
   * @param {KeyboardEvent} event - keypress event
   */
  onKeyPressListener(event: KeyboardEvent): boolean {
    if (event.key === 'Enter') {
      if (event.shiftKey) {
        return true;
      }

      this.moveCursorToNextRow();
    }

    return event.key !== 'Enter';
  };

  /**
   * Prevents tab keydown event from bubbling
   * so that it only works inside the table
   *
   * @param {KeyboardEvent} event - keydown event
   */
  onKeyDownListener(event: KeyboardEvent): void {
    if (event.key === 'Tab' || event.key === 'Backspace') {
      event.stopPropagation();
    }
  }

  /**
   * Set the coordinates of the cell that the focus has moved to
   *
   * @param {FocusEvent} event - focusin event
   */
  focusInTableListener(event: FocusEvent): void {
    const cell = event.target as HTMLElement;
    const row = this.getRowByCell(cell);

    this.focusedCell = {
      row: Array.from(this.table!.querySelectorAll(`.${CSS.row}`)).indexOf(row) + 1,
      column: Array.from(row.querySelectorAll(`.${CSS.cell}`)).indexOf(cell) + 1
    };
  }

  /**
   * Unselect row/column
   * Close toolbox menu
   * Hide toolboxes
   *
   * @returns {void}
   */
  hideToolboxes(): void {
    this.hideRowToolbox();
    this.hideColumnToolbox();
    this.updateToolboxesPosition();
  }

  /**
   * Unselect row, close toolbox
   *
   * @returns {void}
   */
  hideRowToolbox(): void {
    this.unselectRow();
    this.toolboxRow.hide();
  }
  /**
   * Unselect column, close toolbox
   *
   * @returns {void}
   */
  hideColumnToolbox(): void {
    this.unselectColumn();

    this.toolboxColumn.hide();
  }

  /**
   * Set the cursor focus to the focused cell
   *
   * @returns {void}
   */
  focusCell(..._args: unknown[]): void {
    this.focusedCellElem.focus();
  }

  /**
   * Get current focused element
   *
   * @returns {HTMLElement} - focused cell
   */
  get focusedCellElem(): HTMLElement {
    const { row, column } = this.focusedCell;

    return this.getCell(row, column);
  }

  /**
   * Update toolboxes position
   *
   * @param {number} row - hovered row
   * @param {number} column - hovered column
   */
  updateToolboxesPosition(row: number = this.hoveredRow, column: number = this.hoveredColumn): void {
    if (!this.isColumnMenuShowing) {
      // Bounds guard: the coordinate may be 0 (initial state, or the explicit
      // updateToolboxesPosition(0, 0) reset after addRow), in which case the
      // toolbox must stay hidden rather than render at a negative calc() offset.
      if (column > 0 && column <= this.numberOfColumns) {
        this.toolboxColumn.show(() => {
          return {
            style: {
              left: `calc((100% - var(--cell-size)) / (${this.numberOfColumns} * 2) * (1 + (${column} - 1) * 2))`
            },
            numberOfColumns: this.numberOfColumns,
            currentColumn: column
          };
        });
      }
    }

    if (!this.isRowMenuShowing) {
      // Bounds guard: see the column branch above. Row 0 means "no hovered row";
      // showing the toolbox then would call getRow(0) and mis-position it.
      if (row > 0 && row <= this.numberOfRows) {
        this.toolboxRow.show(() => {
          const hoveredRowElement = this.getRow(row);
          const { fromTopBorder } = $.getRelativeCoordsOfTwoElems(this.table!, hoveredRowElement);
          const { height } = hoveredRowElement.getBoundingClientRect();

          return {
            style: {
              top: `${Math.ceil(fromTopBorder + height / 2)}px`
            },
            numberOfRows: this.numberOfRows,
            currentRow: row
          };
        });
      }
    }
  }

  /**
   * Makes the first row headings
   *
   * @param {boolean} withHeadings - use headings row or not
   */
  setHeadingsSetting(withHeadings: boolean | undefined): void {
    this.tunes.withHeadings = withHeadings as boolean;

    if (withHeadings) {
      this.table!.classList.add(CSS.withHeadings);
      this.addHeadingAttrToFirstRow();
    } else {
      this.table!.classList.remove(CSS.withHeadings);
      this.removeHeadingAttrFromFirstRow();
    }
  }

  /**
   * Adds an attribute for displaying the placeholder in the cell
   */
  addHeadingAttrToFirstRow(): void {
    for (let cellIndex = 1; cellIndex <= this.numberOfColumns; cellIndex++) {
      const cell = this.getCell(1, cellIndex);

      if (cell) {
        cell.setAttribute('heading', this.api.i18n.t('Heading'));
      }
    }
  }

  /**
   * Removes an attribute for displaying the placeholder in the cell
   */
  removeHeadingAttrFromFirstRow(): void {
    for (let cellIndex = 1; cellIndex <= this.numberOfColumns; cellIndex++) {
      const cell = this.getCell(1, cellIndex);

      if (cell) {
        cell.removeAttribute('heading');
      }
    }
  }

  /**
   * Add effect of a selected row
   *
   * @param {number} index
   */
  selectRow(index: number): void {
    const row = this.getRow(index);

    if (row) {
      this.selectedRow = index;
      row.classList.add(CSS.rowSelected);
    }
  }

  /**
   * Remove effect of a selected row
   */
  unselectRow(): void {
    if (this.selectedRow <= 0) {
      return;
    }

    const row = this.table!.querySelector(`.${CSS.rowSelected}`);

    if (row) {
      row.classList.remove(CSS.rowSelected);
    }

    this.selectedRow = 0;
  }

  /**
   * Add effect of a selected column
   *
   * @param {number} index
   */
  selectColumn(index: number): void {
    for (let i = 1; i <= this.numberOfRows; i++) {
      const cell = this.getCell(i, index);

      if (cell) {
        cell.classList.add(CSS.cellSelected);
      }
    }

    this.selectedColumn = index;
  }

  /**
   * Remove effect of a selected column
   */
  unselectColumn(): void {
    if (this.selectedColumn <= 0) {
      return;
    }

    const cells = this.table!.querySelectorAll(`.${CSS.cellSelected}`);

    Array.from(cells).forEach(column => {
      column.classList.remove(CSS.cellSelected);
    });

    this.selectedColumn = 0;
  }

  /**
   * Calculates the row and column that the cursor is currently hovering over
   * The search was optimized from O(n) to O (log n) via bin search to reduce the number of calculations
   *
   * @param {Event} event - mousemove event
   * @returns hovered cell coordinates as an integer row and column
   */
  getHoveredCell(event: MouseEvent): { row: number; column: number } {
    let hoveredRow = this.hoveredRow;
    let hoveredColumn = this.hoveredColumn;
    const { width, height, x, y } = $.getCursorPositionRelativeToElement(this.table!, event);

    // Looking for hovered column
    if (x >= 0) {
      hoveredColumn = this.binSearch(
        this.numberOfColumns,
        (mid: number) => this.getCell(1, mid),
        (coords: any) => (x < coords.fromLeftBorder),
        (coords: any) => (x > (width - coords.fromRightBorder))
      );
    }

    // Looking for hovered row
    if (y >= 0) {
      hoveredRow = this.binSearch(
        this.numberOfRows,
        (mid: number) => this.getCell(mid, 1),
        (coords: any) => (y < coords.fromTopBorder),
        (coords: any) => (y > (height - coords.fromBottomBorder))
      );
    }

    return {
      row: hoveredRow || this.hoveredRow,
      column: hoveredColumn || this.hoveredColumn
    };
  }

  /**
   * Looks for the index of the cell the mouse is hovering over.
   * Cells can be represented as ordered intervals with left and
   * right (upper and lower for rows) borders inside the table, if the mouse enters it, then this is our index
   *
   * @param {number} numberOfCells - upper bound of binary search
   * @param {function} getCell - function to take the currently viewed cell
   * @param {function} beforeTheLeftBorder - determines the cursor position, to the left of the cell or not
   * @param {function} afterTheRightBorder - determines the cursor position, to the right of the cell or not
   * @returns {number}
   */
  binSearch(numberOfCells: number, getCell: (mid: number) => HTMLElement, beforeTheLeftBorder: (coords: any) => boolean, afterTheRightBorder: (coords: any) => boolean): number {
    let leftBorder = 0;
    let rightBorder = numberOfCells + 1;
    let totalIterations = 0;
    let mid!: number;

    while (leftBorder < rightBorder - 1 && totalIterations < 10) {
      mid = Math.ceil((leftBorder + rightBorder) / 2);

      const cell = getCell(mid);
      const relativeCoords = $.getRelativeCoordsOfTwoElems(this.table!, cell);

      if (beforeTheLeftBorder(relativeCoords)) {
        rightBorder = mid;
      } else if (afterTheRightBorder(relativeCoords)) {
        leftBorder = mid;
      } else {
        break;
      }

      totalIterations++;
    }

    return mid;
  }

  /**
   * Collects data from cells into a two-dimensional array
   *
   * @returns {string[][]}
   */
  getData(): string[][] {
    const data = [];

    for (let i = 1; i <= this.numberOfRows; i++) {
      const row = this.table!.querySelector(`.${CSS.row}:nth-child(${i})`) as HTMLElement;
      const cells = Array.from(row.querySelectorAll(`.${CSS.cell}`));
      const isEmptyRow = cells.every(cell => !cell.textContent!.trim());

      if (isEmptyRow) {
        continue;
      }

      data.push(cells.map(cell => cell.innerHTML));
    }

    return data;
  }

  /**
   * Remove listeners on the document
   */
  destroy(): void {
    document.removeEventListener('click', this.documentClicked);
  }
}
